import "./announcement.css";

export interface AnnouncementProps {
  text: string;
  linkLabel: string;
  tone: "accent" | "yellow" | "dark" | "gradient";
  align: "center" | "left";
}

export function AnnouncementRender({ text, linkLabel, tone, align }: AnnouncementProps) {
  return (
    <div className="p1-announcement" data-tone={tone} data-align={align}>
      <span className="p1-announcement__text">{text}</span>
      {linkLabel && <span className="p1-announcement__link">{linkLabel}</span>}
    </div>
  );
}

import type { ComponentConfig } from "@puckeditor/core";
import { defineMeta } from '../define-meta';
import { AnnouncementRender, type AnnouncementProps } from "./announcement";
export type { AnnouncementProps };

export const AnnouncementBlock: ComponentConfig<AnnouncementProps> = {
  fields: {
    text: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "Short announcement message. 1 sentence." },
    },
    linkLabel: {
      type: "text" as const,
      contentEditable: true,
      visible: false,
      ai: { instructions: "CTA label after the message. E.g. Read more →. Leave blank to omit." },
    },
    tone: {
      type: "select" as const,
      options: [
        { label: "Accent", value: "accent" },
        { label: "Yellow", value: "yellow" },
        { label: "Dark", value: "dark" },
        { label: "Gradient", value: "gradient" },
      ],
    },
    align: {
      type: "radio" as const,
      options: [
        { label: "Center", value: "center" },
        { label: "Left", value: "left" },
      ],
    },
  },
  defaultProps: {
    text: "Something new just launched — take a look.",
    linkLabel: "Read the announcement →",
    tone: "accent",
    align: "center",
  },
  render: AnnouncementRender,
};

export const meta = defineMeta({
  title: 'Announcement',
  description: 'Slim banner strip with a text message and optional link label in themed tones (purple/yellow/dark/gradient); use for site-wide notices.',
  categories: ["attention"],
  published: true,
});

.p1-announcement {
  align-items: center;
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  padding-block: 0.75rem;
  padding-inline: var(--p1-space-lg);
}

.p1-announcement[data-align="center"] { justify-content: center; }
.p1-announcement[data-align="left"] { justify-content: start; }

.p1-announcement[data-tone="accent"] {
  background-color: var(--p1-accent);
  color: var(--p1-fg-inverse);
}
.p1-announcement[data-tone="yellow"] {
  background-color: var(--p1-warning);
  color: var(--p1-fg-default);
}
.p1-announcement[data-tone="dark"] {
  background-color: var(--p1-surface-dark);
  color: var(--p1-fg-inverse);
}
.p1-announcement[data-tone="gradient"] {
  background: linear-gradient(90deg, var(--p1-gradient-from), var(--p1-gradient-via), var(--p1-gradient-to));
  color: var(--p1-fg-inverse);
}

.p1-announcement__text { font-size: var(--p1-text-sm); font-weight: var(--p1-weight-medium); }

.p1-announcement__link { font-size: var(--p1-text-sm); font-weight: var(--p1-weight-bold); }
.p1-announcement[data-tone="accent"] .p1-announcement__link { color: var(--p1-warning); }
.p1-announcement[data-tone="yellow"] .p1-announcement__link { color: var(--p1-accent); }
.p1-announcement[data-tone="dark"] .p1-announcement__link { color: var(--p1-warning); }
.p1-announcement[data-tone="gradient"] .p1-announcement__link { color: var(--p1-warning); }

